{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, extname, join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const root = dirname(fileURLToPath(import.meta.url));
const publicDir = join(root, 'public');
const dbPath = process.env.DB_PATH || join(root, 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
  )
`);
// Existing Task 001/002 databases gain the archive field without losing data.
const projectColumns = db.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
db.exec(`
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  )
`);

const contentTypes = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
};

async function sendFile(response, filePath) {
  try {
    const contents = await readFile(filePath);
    response.writeHead(200, { 'Content-Type': contentTypes[extname(filePath)] || 'application/octet-stream' });
    response.end(contents);
  } catch {
    response.writeHead(404).end('Not found');
  }
}

function sendJson(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (url.pathname === '/api/projects' && request.method === 'GET') {
    const projects = db.prepare(`
      SELECT p.id, p.name, p.archived,
        COUNT(t.id) AS total_count,
        COALESCE(SUM(t.completed), 0) AS completed_count
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id
    `).all().map((project) => ({
      ...project,
      id: Number(project.id),
      archived: Boolean(project.archived),
      total_count: Number(project.total_count),
      completed_count: Number(project.completed_count),
    }));
    return sendJson(response, 200, projects);
  }
  const projectRoute = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectRoute && request.method === 'PATCH') {
    const body = await readJson(request);
    if (typeof body?.archived !== 'boolean') return sendJson(response, 400, { error: 'Archive state is required' });
    const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(body.archived ? 1 : 0, Number(projectRoute[1]));
    if (!result.changes) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, { id: Number(projectRoute[1]), archived: body.archived });
  }
  if (url.pathname === '/api/projects' && request.method === 'POST') {
    const body = await readJson(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name });
  }
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    const taskId = taskRoute[2] ? Number(taskRoute[2]) : null;
    const project = db.prepare('SELECT id, archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (!taskId && request.method === 'GET') {
      const tasks = db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId)
        .map((task) => ({ ...task, id: Number(task.id), completed: Boolean(task.completed) }));
      return sendJson(response, 200, tasks);
    }
    if (!taskId && request.method === 'POST') {
      if (project.archived) return sendJson(response, 409, { error: 'Archived projects cannot be changed' });
      const body = await readJson(request);
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) return sendJson(response, 400, { error: 'Task title is required' });
      const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      return sendJson(response, 201, { id: Number(result.lastInsertRowid), title, completed: false });
    }
    if (taskId && request.method === 'PATCH') {
      if (project.archived) return sendJson(response, 409, { error: 'Archived projects cannot be changed' });
      const body = await readJson(request);
      if (typeof body?.completed !== 'boolean') return sendJson(response, 400, { error: 'Completion state is required' });
      const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?')
        .run(body.completed ? 1 : 0, taskId, projectId);
      if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
      return sendJson(response, 200, { id: taskId, completed: body.completed });
    }
    return sendJson(response, 405, { error: 'Method not allowed' });
  }
  if (request.method === 'GET' && url.pathname.startsWith('/api/')) {
    return sendJson(response, 404, { error: 'Not found' });
  }

  if (request.method === 'GET' && url.pathname.startsWith('/projects/')) {
    return sendFile(response, join(publicDir, 'index.html'));
  }
  if (request.method === 'GET' && url.pathname.startsWith('/assets/')) {
    const asset = url.pathname.slice('/assets/'.length);
    if (!['app.js', 'style.css'].includes(asset)) return response.writeHead(404).end('Not found');
    return sendFile(response, join(publicDir, asset));
  }
  if (request.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
    return sendFile(response, join(publicDir, 'index.html'));
  }
  response.writeHead(404).end('Not found');
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');

function close() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGINT', close);
process.on('SIGTERM', close);
const app = document.querySelector('#app');
let listRenderId = 0;

async function getProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Unable to load projects');
  return response.json();
}

async function getTasks(projectId) {
  const response = await fetch(`/api/projects/${projectId}/tasks`);
  if (!response.ok) throw new Error('Unable to load tasks');
  return response.json();
}

function makeButton(label, onClick, className = '') {
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = label;
  if (className) button.className = className;
  button.addEventListener('click', onClick);
  return button;
}

async function renderList(errorMessage = '', selectedFilter = 'active') {
  const renderId = ++listRenderId;
  app.replaceChildren();
  const heading = document.createElement('h1');
  heading.textContent = 'Workboard';
  app.append(heading);

  if (errorMessage) {
    const alert = document.createElement('p');
    alert.className = 'alert';
    alert.setAttribute('role', 'alert');
    alert.textContent = errorMessage;
    app.append(alert);
  }

  const form = document.createElement('form');
  form.className = 'project-form';
  const field = document.createElement('div');
  field.className = 'field';
  const label = document.createElement('label');
  label.htmlFor = 'project-name';
  label.textContent = 'Project name';
  const input = document.createElement('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  field.append(label, input);
  const submit = document.createElement('button');
  submit.type = 'submit';
  submit.textContent = 'Create project';
  form.append(field, submit);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      await renderList('Project name is required');
      document.querySelector('#project-name')?.focus();
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    if (!response.ok) {
      await renderList('Unable to create project');
      return;
    }
    await renderList();
  });
  app.append(form);

  const filterField = document.createElement('div');
  filterField.className = 'filter-field';
  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'project-filter';
  filterLabel.textContent = 'Project filter';
  const filter = document.createElement('select');
  filter.id = 'project-filter';
  for (const value of ['Active', 'Archived']) {
    const option = document.createElement('option');
    option.value = value.toLowerCase();
    option.textContent = value;
    filter.append(option);
  }
  filter.value = selectedFilter;
  filterField.append(filterLabel, filter);
  app.append(filterField);

  try {
    const projects = await getProjects();
    // Several list renders can overlap (for example after a filter change and
    // a mutation). Only the newest render owns the rows in the shared app node.
    if (renderId !== listRenderId) return;
    for (const project of projects) {
      if (filter.value === 'active' && project.archived) continue;
      if (filter.value === 'archived' && !project.archived) continue;
      const row = document.createElement('section');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const name = document.createElement('span');
      name.className = 'project-name';
      name.textContent = project.name;
      const summary = document.createElement('span');
      summary.dataset.testid = 'project-summary';
      summary.textContent = `${project.completed_count}/${project.total_count} completed`;
      row.append(name, summary, makeButton('Open project', () => {
        history.pushState({}, '', `/projects/${project.id}`);
        renderRoute();
      }));
      row.append(makeButton(project.archived ? 'Restore project' : 'Archive project', async () => {
        const response = await fetch(`/api/projects/${project.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ archived: !project.archived }),
        });
        if (response.ok) renderList('', filter.value);
      }));
      app.append(row);
    }
    filter.addEventListener('change', () => renderList('', filter.value));
  } catch {
    if (renderId !== listRenderId) return;
    const error = document.createElement('p');
    error.className = 'alert';
    error.setAttribute('role', 'alert');
    error.textContent = 'Unable to load projects';
    app.append(error);
  }
}

async function renderProject(id) {
  const projects = await getProjects();
  const project = projects.find((item) => String(item.id) === id);
  if (!project) return renderList('Project not found');
  app.replaceChildren();
  app.append(makeButton('Projects', () => {
    history.pushState({}, '', '/');
    renderRoute();
  }, 'back-button'));
  const heading = document.createElement('h1');
  heading.textContent = project.name;
  app.append(heading);
  if (project.archived) {
    const status = document.createElement('p');
    status.textContent = 'Archived project';
    app.append(status);
  }

  const form = document.createElement('form');
  form.className = 'task-form';
  const field = document.createElement('div');
  field.className = 'field';
  const label = document.createElement('label');
  label.htmlFor = 'task-title';
  label.textContent = 'Task title';
  const input = document.createElement('input');
  input.id = 'task-title';
  input.name = 'title';
  input.type = 'text';
  field.append(label, input);
  const submit = document.createElement('button');
  submit.type = 'submit';
  submit.textContent = 'Create task';
  submit.disabled = project.archived;
  input.disabled = project.archived;
  form.append(field, submit);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const title = input.value.trim();
    if (!title) return renderProjectWithAlert(id, 'Task title is required');
    const response = await fetch(`/api/projects/${id}/tasks`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
    });
    if (!response.ok) return renderProjectWithAlert(id, 'Unable to create task');
    renderProject(id);
  });
  app.append(form);

  const filterField = document.createElement('div');
  filterField.className = 'filter-field';
  const filterLabel = document.createElement('label');
  filterLabel.htmlFor = 'task-filter';
  filterLabel.textContent = 'Task filter';
  const filter = document.createElement('select');
  filter.id = 'task-filter';
  for (const value of ['All', 'Open', 'Completed']) {
    const option = document.createElement('option');
    option.value = value.toLowerCase();
    option.textContent = value;
    filter.append(option);
  }
  filterField.append(filterLabel, filter);
  app.append(filterField);

  const taskList = document.createElement('div');
  taskList.className = 'task-list';
  app.append(taskList);
  let tasks;
  try {
    tasks = await getTasks(id);
  } catch {
    taskList.textContent = 'Unable to load tasks';
    taskList.className = 'alert';
    return;
  }
  const renderTasks = () => {
    taskList.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'open' && task.completed) continue;
      if (filter.value === 'completed' && !task.completed) continue;
      const row = document.createElement('section');
      row.className = 'task-row';
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.className = 'task-title';
      title.textContent = task.title;
      const checkboxLabel = document.createElement('label');
      checkboxLabel.className = 'completion-control';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        const response = await fetch(`/api/projects/${id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        if (response.ok) {
          task.completed = checkbox.checked;
          renderTasks();
        } else {
          checkbox.checked = task.completed;
          checkbox.disabled = false;
        }
      });
      checkboxLabel.append(checkbox);
      row.append(title, checkboxLabel);
      taskList.append(row);
    }
  };
  filter.addEventListener('change', renderTasks);
  renderTasks();
}

async function renderProjectWithAlert(id, message) {
  await renderProject(id);
  const alert = document.createElement('p');
  alert.className = 'alert';
  alert.setAttribute('role', 'alert');
  alert.textContent = message;
  app.insertBefore(alert, app.querySelector('.task-form'));
}

